SELECT 'invoice_headers' AS section, row_to_json(s)::text AS data FROM (SELECT count(*) FILTER(WHERE superseded_at IS NULL) AS current_rows,count(*) FILTER(WHERE superseded_at IS NOT NULL) AS historical_rows FROM canonical_invoice) s;
SELECT 'invoice_lines' AS section,row_to_json(s)::text AS data FROM (SELECT count(*) FILTER(WHERE superseded_at IS NULL) AS current_rows,count(*) FILTER(WHERE superseded_at IS NOT NULL) AS historical_rows FROM canonical_invoice_line) s;
SELECT 'legacy_line_parent_candidates' AS section,row_to_json(s)::text AS data FROM (WITH h AS (SELECT invoice_number,count(DISTINCT logical_entity_id) n FROM canonical_invoice WHERE superseded_at IS NULL GROUP BY invoice_number) SELECT count(*) FILTER(WHERE h.n=1) AS unique_number_candidates,count(*) FILTER(WHERE h.n>1) AS ambiguous_number_candidates,count(*) FILTER(WHERE h.n IS NULL) AS orphan_candidates FROM canonical_invoice_line l LEFT JOIN h USING(invoice_number) WHERE l.superseded_at IS NULL /*LEGACY_PARENT_FILTER*/) s;
SELECT 'tax_net_reclassification' AS section,row_to_json(s)::text AS data FROM (WITH candidates AS (SELECT trading_date FROM canonical_daily_sales WHERE superseded_at IS NULL GROUP BY trading_date HAVING count(*)>1 AND max(total_sales)-min(total_sales)<=0.01 AND (max(gst_total)-min(gst_total)>0.01 OR max(net_total)-min(net_total)>0.01)) SELECT count(*) AS dates_with_equal_gross_different_components,count(*) FILTER(WHERE r.resolution_type='agreed' AND NOT r.has_conflict) AS currently_false_agreement FROM candidates c LEFT JOIN resolved_daily_sales r USING(trading_date)) s;
SELECT 'inventory_projection_comparison' AS section,row_to_json(s)::text AS data FROM (WITH c AS (SELECT invoice_date,sum(line_total) total FROM canonical_invoice_line WHERE superseded_at IS NULL GROUP BY invoice_date) SELECT count(*) FILTER(WHERE r.authoritative_source IS DISTINCT FROM 'manual' AND (r.trading_date IS NULL OR c.invoice_date IS NULL OR r.purchases IS DISTINCT FROM c.total)) AS nonmanual_mismatch_dates FROM c FULL JOIN resolved_inventory_day r ON r.trading_date=c.invoice_date) s;
SELECT 'historical_date_changes' AS section,row_to_json(s)::text AS data FROM (SELECT count(*) AS invoice_line_entities_with_changed_dates FROM (SELECT logical_entity_id FROM canonical_invoice_line GROUP BY logical_entity_id HAVING count(DISTINCT invoice_date)>1) x) s;
SELECT 'product_sales' AS section,row_to_json(s)::text AS data FROM (SELECT count(*) FILTER(WHERE superseded_at IS NULL) current_rows,count(*) FILTER(WHERE superseded_at IS NOT NULL) historical_rows FROM canonical_product_sales) s;
SELECT 'stock_observations' AS section,row_to_json(s)::text AS data FROM (SELECT (SELECT count(*) FROM canonical_stocktake) AS headers_all_versions,(SELECT count(*) FROM canonical_stock_count) AS counts_all_versions,(SELECT count(*) FROM canonical_wastage) AS waste_all_versions,(SELECT count(*) FROM canonical_stock_count WHERE superseded_at IS NULL AND quantity_on_hand=0) AS zero_current_counts_requiring_source_evidence) s;
SELECT 'forecast_runs' AS section,row_to_json(s)::text AS data FROM (SELECT status,count(*) AS runs FROM forecast_run GROUP BY status) s;
SELECT 'invoice_pdf_links' AS section,row_to_json(s)::text AS data FROM (SELECT count(*) AS links FROM invoice_pdf_link) s;
